    "note": "來源：奧地利寶盒（原出處：台東食冊Café書局）。烘焙前裝飾用的蛋白、粗粒黃糖原文寫「適量」（可省略）。替代：糖粉可取代細砂糖，甜度略低、更細緻；要給小朋友吃可省略咖啡，另加 1/2 小匙香草精或 1 小匙香草糖。即溶咖啡粉要用原味的，三合一有糖和添加物不適合。食譜中的核桃沒有先烤過，先烘烤或用無油乾鍋炒香會更香。切片時黏刀可在刀上篩少許麵粉。烤盤要鋪烘焙紙（不是白報紙），用洞洞矽膠墊底部受熱上色更均勻。同一爐的餅乾形狀厚薄要盡量一致；上色從外緣開始往中心，外緣開始上色時很快就可以出爐；要確實烤熟才香、才好保存。保存：放有蓋容器（作者偏好有蓋的金屬餅乾盒），正確烘焙可保存 2 週。想讓餅乾軟一點給牙口不好的長輩：把一片蘋果放小碟子裡（不包起來、不碰到餅乾）放進餅乾盒 1～2 天。麵團冷凍：用保鮮膜確實包兩層，建議分成 300 公克大小、厚度不超過 3 公分；要用時放冷藏室慢慢解凍，不要在室溫解凍，否則外軟內冰，做壓花餅乾時容易變形開裂。"
