    "steps": [
      "烤箱預熱上下溫 175°C（旋風功能 155°C），大烤盤鋪烘焙紙或矽膠烘焙墊。",
      "所有食材放進容器，用手壓合成一個麵團；只用壓、翻的方式，不揉麵，不平滑沒關係。完成的麵團質地乾燥、不黏手；太黏就稍微加點麵粉調整。",
      "工作檯和擀麵杖撒麵粉，把麵團擀成厚度約 0.5～0.7 公分的麵餅。",
      "用利刀切成塊狀或條狀（示範成品是 2.5 公分見方）。",
      "排在鋪好烤紙的烤盤上，間距不必太大。",
      "表面再撒少許黑胡椒粉、辣椒粉或喜歡的乾燥香草葉（可省略）。",
      "入爐，上下溫 175°C（旋風 155°C）烤 15～25 分鐘，依餅乾實際大小與厚度調整；要烤到乾燥、起司散發香氣、上方上色、底部均勻乾燥，把水份烤乾才酥香、也較耐放。",
      "出爐後在烤盤上留 10 分鐘，再移到網架上冷卻；完全冷卻後立即裝入餅乾盒，避免吸收空氣中的潮氣。"
    ],
    "note": "來源：奧地利寶盒。黑胡椒粉、乾辣椒粉原文寫「適量」。乾燥香草可用迷迭香、羅勒、奧勒岡、百里香、馬郁蘭等，家裡現有的（例如做 Pizza 的香草葉）可混合使用。可加少量黑白芝麻、切碎的南瓜籽、葵花籽、各種堅果。起司替代：可用其他熟成期較長的乾酪起司（瑞士、帕瑪森、高山起司等），乳脂肪至少 40% 以上；可混合不同起司；熟成超過六個月的起司較鹹，要稍減鹽。可用全麥麵粉替換一半份量的低筋麵粉。保存：可提前做好、仔細封存後冷凍，可保存 3 個月，取出後用小烤箱略烤即恢復酥脆。冷凍生麵團：先切塊放大盤子冷凍定型再裝袋，烘烤時不用回溫直接入爐，時間較長。補充（2019.11.07）：長形餅乾比圓形熟得快；不喜歡上色太深，可在邊緣開始上色時降溫約 20°C、拉長烘烤時間把水份烤乾，餅乾會更酥。"
