    "note": "原配方只寫數字沒寫單位，推定為克。原食譜沒有檸檬，可自行加檸檬皮。烤出肚臍的關鍵：1. 泡打粉開封後會受潮失效，失效了烤溫再高也沒用；2. 麵糊太濃稠需要更多二氧化碳才撐得起肚臍；3. 麵糊太稠可加 5～10 克濕性材料（牛奶或酒），或減少麵粉，判斷法：擠花袋裝好冷藏 1 小時後用手捏覺得有點硬就是太稠；4. 麵糊做好要冷藏讓它穩定，通常約 1 小時就夠，冰過的麵糊肚臍外型特別好看；5. 烤溫通常約 200 度、放烤箱下層，烤模下方不要再多墊一個烤盤，溫度太低肚臍會比較小。"
