      "模具墊白報紙，先倒一半麵糊，撒上沾了乾粉的蘭姆酒葡萄乾，再均勻鋪上 2/3 的奶酥，最後倒入剩下的麵糊刮平。",
      "烤箱 180°C 預熱，先烤 10 分鐘，撒上剩下的奶酥，改 160°C 再烤 15 分鐘；表面金黃、中心用叉子確認不沾即可出爐。"
