    "note": "模具 20×30×4（約等於八吋蛋糕模，5～6 個蛋的配方）；用 20×20 方型模會更澎更漂亮，也可用八吋模或任何方型模。蛋黃 85g 約 4～5 個、蛋白 170g 約 5～6 個。葡萄乾原文 50～100g，取較小值；蘭姆酒適量。椰子粉可不加。蛋糕體不需要減糖，本身不甜，搭配奶酥剛好；可再加水滴巧克力，蘭姆酒葡萄乾可改蔓越莓。來源：蛋糕體參考《美味糕點新主張》（薛妃娟）。"
