      "蛋糕體：抹茶粉加牛奶加熱到抹茶粉溶解後關火。",
      "加入植物油拌勻，再加蛋黃拌勻，最後加入過篩的低筋麵粉拌勻成蛋黃糊。",
      "蛋白加細砂糖與檸檬汁打到偏乾性，再與蛋黃糊拌勻。",
      "烤箱上火200／下火130預熱；以上火200／下火130烤10分鐘，之後把烤箱門稍微打開，改上火150／下火130再烤10分鐘完成。",
